/**
 * Builds the station's machines from the catalog and places them in the station frame.
 * @param {object} o
 * @param {object} o.registry  the catalog (components, products, ops)
 * @param {object} o.ctx       build context: materials, belt height
 * @returns {{ root: THREE.Group, equipment: object }}
 */
export function build({ registry, ctx }) {
  const root = new THREE.Group();
  root.name = 'Fa Filling 1/2';
  const equipment = {};

  // belt: Flat-belt conveyor for loose units (cans, bottles, cases): drums, return...
  equipment.belt = registry.buildComponent('beltConveyor', { length: 2.4 }, ctx);
  root.add(equipment.belt.root);

  // doser: A machine put together from parts (basic frames, axes, tools), each on a...
  equipment.doser = registry.buildComponent('composite', {
    parts: [
      { id: 'frame', type: 'portalFrame', params: { span: 0.8, height: 2 } },
      {
        id: 'cross',
        type: 'linearAxis',
        params: { stroke: 0.5, hang: true },
        on: 'frame.beam',
        rotationY: 1.5707963267948966,
      },
      {
        id: 'lift',
        type: 'verticalAxis',
        params: { stroke: 0.25, bodyLength: 0.35 },
        on: 'cross.carriage',
      },
      {
        id: 'nozzle',
        type: 'dispenseNozzle',
        params: { jetLength: 0.15, liquid: 'oil' },
        on: 'lift.ram',
      },
    ],
    motions: { lower: 'lift.extend', flow: 'nozzle.flow' },
    anchors: { tool: 'nozzle' },
  }, ctx);
  root.add(equipment.doser.root);

  return { root, equipment };
}
